# Shared HTML helpers
SITE='https://soyorica.github.io'

def head(title, desc, path, lang='ja', alt_path=None, schema=None):
    canonical=SITE+path
    if alt_path is None:
        alt_path = ('/en'+path if lang=='ja' else path.replace('/en','',1) or '/')
    ja_path = path if lang=='ja' else path.replace('/en','',1) or '/'
    en_path = path if lang=='en' else ('/en/' if path=='/' else '/en'+path)
    schema_text=''
    if schema:
        schema_text='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False,separators=(',',':'))+'</script>'
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="ja" href="{SITE+ja_path}"><link rel="alternate" hreflang="en" href="{SITE+en_path}"><link rel="alternate" hreflang="x-default" href="{SITE+ja_path}"><meta property="og:type" content="website"><meta property="og:site_name" content="Soyorica"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SITE}/assets/og.png"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#11364F"><link rel="icon" href="/assets/favicon-32.png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="stylesheet" href="/assets/site.css">{schema_text}</head><body><a class="skip" href="#main">{'本文へ移動' if lang=='ja' else 'Skip to content'}</a>'''

def header(lang='ja'):
    if lang=='ja':
        base=''; labels=[('製品','/products/'),('説明書','/docs/'),('インストール','/install/'),('FAQ','/faq/')]; langlink=('/en/','EN'); booth='BOOTH'
    else:
        base='/en'; labels=[('Products','/en/products/'),('Manuals','/en/docs/'),('Install','/en/install/'),('FAQ','/en/faq/')]; langlink=('/','JA'); booth='BOOTH'
    links=''.join([f'<a href="{u}">{t}</a>' for t,u in labels])
    return f'''<header class="site-header"><nav class="nav" aria-label="{'メインナビゲーション' if lang=='ja' else 'Main navigation'}"><a class="brand" href="{base or '/'}"><img src="/assets/icon.png" width="28" height="28" alt=""><span>Soyorica</span></a><button class="menu-btn" type="button" aria-expanded="false" aria-label="{'メニューを開く' if lang=='ja' else 'Open menu'}">Menu</button><div class="nav-links">{links}<a class="nav-cta" href="https://soyorica.booth.pm/" rel="external">{booth}</a><a class="lang" href="{langlink[0]}">{langlink[1]}</a></div></nav></header>'''

def footer(lang='ja'):
    if lang=='ja':
        p='/'; groups=[('製品',[('HairSway','/products/hairsway/'),('MathMotionGraph','/products/mathmotiongraph/')]),('サポート',[('説明書','/docs/'),('インストール','/install/'),('FAQ','/faq/')]),('購入・配布',[('BOOTHショップ','https://soyorica.booth.pm/'),('HairSway','https://soyorica.booth.pm/items/8676362')])]
        note='DaVinci Resolve / Fusion向けの制作ツール。'; copy='© 2026 Soyorica. DaVinci Resolve is a trademark of Blackmagic Design Pty. Ltd. Soyorica products are not official Blackmagic Design products.'
    else:
        p='/en/'; groups=[('Products',[('HairSway','/en/products/hairsway/'),('MathMotionGraph','/en/products/mathmotiongraph/')]),('Support',[('Manuals','/en/docs/'),('Install','/en/install/'),('FAQ','/en/faq/')]),('Store',[('BOOTH Shop','https://soyorica.booth.pm/'),('HairSway','https://soyorica.booth.pm/items/8676362')])]
        note='Production tools for DaVinci Resolve / Fusion.'; copy='© 2026 Soyorica. DaVinci Resolve is a trademark of Blackmagic Design Pty. Ltd. Soyorica products are not official Blackmagic Design products.'
    cols=f'<div><div class="footer-brand">Soyorica</div><p class="muted">{note}</p></div>'
    for h,items in groups:
        cols+=f'<div><h3>{h}</h3>'+''.join(f'<a href="{u}">{t}</a>' for t,u in items)+'</div>'
    return f'''<footer class="footer"><div class="container"><div class="footer-grid">{cols}</div><div class="copyright">{copy}</div></div></footer><script src="/assets/site.js" defer></script></body></html>'''

def breadcrumbs(items, lang='ja'):
    return '<div class="breadcrumbs">'+' / '.join(f'<a href="{u}">{escape(t)}</a>' if u else escape(t) for t,u in items)+'</div>'

def code_row(value, lang='ja'):
    label='コピー' if lang=='ja' else 'Copy'; copied='コピーしました' if lang=='ja' else 'Copied'
    return f'<div class="code-row"><code>{escape(value)}</code><button class="copy-btn" type="button" data-copy="{escape(value,quote=True)}" data-copied="{copied}">{label}</button></div>'

def write_page(path, content):
    fp=ROOT/path.strip('/')/'index.html' if path!='/' else ROOT/'index.html'
    fp.parent.mkdir(parents=True, exist_ok=True); fp.write_text(content,encoding='utf-8')

