hair_params_ja=[
('Enable','On','全体','HairSwayノード全体の効果をオン／オフします。オフでは入力画像を変形せず出力します。'),('Mix','1.0','全体','元画像と変形後画像の合成比率です。0で元画像、1で変形後のみになります。'),('Master Amount','1.0','全体','各SwayのSway Distanceに掛ける倍率です。複数の揺れ幅をまとめて調整します。'),('Master Speed','1.0','全体','各SwayのSpeedに掛ける倍率です。複数の揺れの速さをまとめて変更します。'),('Frame Rate','24','全体','揺れの時間計算に使うフレームレートです。コンポジションのFPSに合わせます。'),('Start Frame','0','全体','自動揺れを開始するフレームです。指定フレームより前は静止します。'),('Enable Sway','Sway 1のみOn','Sway 1–8','選択したSwayの変形を有効または無効にします。'),('Show Pins in Viewer','Sway 1のみOn','Sway 1–8','そのSwayのピンをViewerに表示します。変形結果には影響しません。'),('Pin Count','4','Sway 1–8','Root Pinを含む使用ピン数です。2〜6。短い髪は3、標準は4、長い髪や大きく曲がる布は5〜6が目安です。'),('Root Pin (fixed)','X=.5 / Y=.82','Sway 1–8','髪や布の根元に置く固定基準点です。髪と頭皮の境界など、動かしたくない根元へ正確に置きます。'),('Pin 2–Pin 6','縦一列','Sway 1–8','Root Pinから毛先へ順番に置く制御点です。最後のピンは先端付近に置きます。'),('Sway Distance (px)','18','Sway 1–8','最大の揺れ幅です。毛先ほど強く適用されます。大きすぎると伸びや不自然な変形が出るため再生しながら調整します。'),('Influence Radius (px)','370','Sway 1–8','ピン列から変形が届く距離です。対象の髪束だけを覆う程度まで小さくするのが基本です。'),('Edge Feather','0.60','Sway 1–8','Influence Radiusの境界を滑らかにします。'),('Speed (cycles/sec)','0.4','Sway 1–8','1秒あたりの揺れ周期です。短い髪はやや速く、長い髪や重い布はやや遅くすると自然に見えやすくなります。'),('Phase (degrees)','Swayごと','Sway 1–8','揺れ始めの位相をずらします。複数の髪束が同時に同じ方向へ動く状態を避けるために使います。'),('Tip Lag (degrees)','55','Sway 1–8','根元から毛先へ揺れの位相が遅れる量です。長い髪では大きめ、短い髪では小さめが目安です。'),('Roundness','0.35','Sway 1–8','横揺れに伴う軸方向の曲がりや縮みを調整します。上げすぎると見かけの長さが不自然に変わる場合があります。'),('Decay (per sec)','0','Sway 1–8','時間経過で揺れを減衰させます。0は継続。短時間だけ揺らす場合は0.5〜2程度から試します。'),('Start Offset (frames)','0','Sway 1–8','選択したSwayだけ開始を指定フレーム数だけ遅らせます。'),('Root Lock','0.22','Sway 1–8','根元側を固定する割合です。頭頂部が浮く、付け根が動く場合に上げます。'),('Root Protection (px)','24','Sway 1–8','Root Pin周辺を完全に変形しない半径です。根元や頭皮が動く場合に増やします。'),('Enable Protection','Off','Protection 1–4','選択したProtection Pinを有効にします。'),('Show Pin in Viewer','Off','Protection 1–4','Protection PinをViewerに表示します。'),('Protection Pin','個別','Protection 1–4','変形から守りたい領域の中心へ置きます。顔、耳、頭頂部、リボンの結び目などに使います。'),('Protection Radius (px)','100','Protection 1–4','Protection Pinを中心に完全に固定する半径です。'),('Edge Feather','0.45','Protection 1–4','保護領域と通常変形領域の境界を滑らかにします。')]
hair_params_en=[
('Enable','On','Global','Enables or disables the entire HairSway effect. When off, the input passes through without deformation.'),('Mix','1.0','Global','Blends the original and deformed images. 0 shows the original; 1 shows the fully deformed result.'),('Master Amount','1.0','Global','Multiplier applied to every Sway Distance, useful for scaling all motion at once.'),('Master Speed','1.0','Global','Multiplier applied to every Sway Speed, useful for changing all sways together.'),('Frame Rate','24','Global','Frame rate used for time-based sway calculation. Match the composition frame rate.'),('Start Frame','0','Global','Frame at which automatic swaying begins. The image stays still before this frame.'),('Enable Sway','Sway 1 on','Sway 1–8','Enables or disables deformation for the selected Sway.'),('Show Pins in Viewer','Sway 1 on','Sway 1–8','Shows that Sway’s pins in the Viewer. It does not change the rendered result.'),('Pin Count','4','Sway 1–8','Number of active pins including the Root Pin, from 2 to 6. A practical starting point is 3 for short hair, 4 for medium hair, and 5–6 for long hair or flexible fabric.'),('Root Pin (fixed)','X=.5 / Y=.82','Sway 1–8','Fixed reference point placed at the root of the strand or fabric section.'),('Pin 2–Pin 6','vertical line','Sway 1–8','Control points arranged from root toward the tip. Place the final active pin near the end of the strand.'),('Sway Distance (px)','18','Sway 1–8','Maximum sway distance. The effect grows toward the tip; very large values can stretch the image unnaturally.'),('Influence Radius (px)','370','Sway 1–8','Distance over which deformation extends from the pin chain. Keep it only as large as needed for the target strand.'),('Edge Feather','0.60','Sway 1–8','Softens the boundary of the Influence Radius.'),('Speed (cycles/sec)','0.4','Sway 1–8','Number of sway cycles per second. Short hair often works slightly faster; long hair or heavy fabric often works slower.'),('Phase (degrees)','per Sway','Sway 1–8','Offsets the starting phase so multiple strands do not move in perfect synchronization.'),('Tip Lag (degrees)','55','Sway 1–8','Adds phase delay from root toward tip. Use more for long hair and less for short hair.'),('Roundness','0.35','Sway 1–8','Controls axial bending and compression that accompanies sideways motion. Excessive values can make the strand length look unstable.'),('Decay (per sec)','0','Sway 1–8','Reduces the motion over time. 0 keeps swaying continuously; for a temporary sway, test roughly 0.5–2 as a starting range.'),('Start Offset (frames)','0','Sway 1–8','Delays only the selected Sway by the specified number of frames.'),('Root Lock','0.22','Sway 1–8','Controls how much of the root region remains fixed. Increase it when the scalp or base of the hair moves.'),('Root Protection (px)','24','Sway 1–8','Radius around the Root Pin that remains completely undeformed.'),('Enable Protection','Off','Protection 1–4','Enables the selected Protection Pin.'),('Show Pin in Viewer','Off','Protection 1–4','Displays that Protection Pin in the Viewer.'),('Protection Pin','per pin','Protection 1–4','Center point of an area protected from deformation, such as the face, ear, scalp, ribbon knot, or fixed clothing.'),('Protection Radius (px)','100','Protection 1–4','Radius around the Protection Pin that remains completely fixed.'),('Edge Feather','0.45','Protection 1–4','Softens the transition between the protected and normally deformed areas.')]

def params_table(rows, lang='ja'):
    headers=('パラメータ','初期値','対象','説明') if lang=='ja' else ('Parameter','Default','Scope','Description')
    tr=''.join('<tr>'+''.join(f'<td>{escape(str(v))}</td>' for v in r)+'</tr>' for r in rows)
    return f'<div class="table-wrap"><table class="param-table"><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+tr+'</tbody></table></div>'

for lang,params in [('ja',hair_params_ja),('en',hair_params_en)]:
    if lang=='ja':
        path='/docs/hairsway/'; title='HairSway 説明書・パラメータ一覧 | Soyorica'; desc='HairSwayの公式説明書。インストール、基本操作、ピン配置、Sway 1〜8、Protection Pin、全パラメータ、トラブル対処を解説します。'; lead='HairSwayの基本操作と、Inspectorに表示されるパラメータの意味をまとめています。'; nav=[('概要','#overview'),('画像の準備','#prepare'),('基本操作','#basic'),('全パラメータ','#parameters'),('Protection Pin','#protection'),('トラブル対処','#trouble')]
        content=f'''<h2 id="overview">概要</h2><p>HairSwayは、レイヤー分けされたイラストの髪、リボン、服の裾などを、キーフレームを使わずに自動で揺らすDaVinci Resolve / Fusion用Fuseです。Viewer上のピン列に沿って画像を局所変形し、1ノードで最大8箇所の揺れを個別に設定できます。</p><h2 id="prepare">画像の準備</h2><p>揺らしたい部分を透明背景の別レイヤーに分けて使用する方法を推奨します。前髪、横髪、後ろ髪、リボン、服の裾などを必要に応じて分離してください。分離されていない画像では、Polygonなどで対象を切り抜いてからHairSwayへ接続します。</p><h2 id="basic">基本操作</h2><ol><li>揺らしたいレイヤーをFusionページへ読み込み、HairSwayを追加してInputへ接続します。</li><li>Sway 1を開き、<code class="inline">Enable Sway 1</code>と<code class="inline">Show Pins in Viewer</code>を有効にします。</li><li><code class="inline">Pin Count</code>を決め、Root Pinを根元に、残りのピンを毛先へ向かって順番に置きます。</li><li><code class="inline">Influence Radius</code>を対象の髪束だけに届く程度まで絞ります。</li><li>再生しながらSway Distance、Speed、Tip Lag、Roundness、Root Lock、Root Protectionを調整します。</li></ol><div class="note">複数の髪束を設定するときは、設定済みSwayの<code class="inline">Show Pins in Viewer</code>をオフにしてから次のSwayを表示すると、ピンを選びやすくなります。</div><h2 id="parameters">全パラメータ</h2>{params_table(params,'ja')}<h2 id="protection">Protection Pin</h2><p>Protection Pinは、すべてのSwayによる変形から特定領域を保護します。頭頂部、顔、耳、髪の付け根、リボンの結び目、服の固定部分などに使えます。最大4個です。</p><p>頭頂部や顔が動く場合は、Root Pinの位置→Root Lock→Root Protection→Influence Radius→Protection Pinの順に見直すと原因を切り分けやすくなります。</p><h2 id="trouble">トラブル対処</h2><h3>頭頂部や顔まで動く</h3><ol><li>Root Pinを髪と頭皮の境界へ置き直す。</li><li>Root Lockを0.30〜0.45程度まで上げて確認する。</li><li>Root Protectionを増やす。</li><li>Influence Radiusを髪束の幅に合わせて小さくする。</li><li>必要ならProtection Pinを置く。</li></ol><h3>再生が重い</h3><p>Viewerのプロキシ解像度を下げ、未使用のSwayをオフにし、必要以上のSwayを使わないようにします。最終確認時にフル解像度へ戻してください。距離・半径は元解像度基準で自動調整されます。</p>'''
    else:
        path='/en/docs/hairsway/'; title='HairSway Manual & Parameter Reference | Soyorica'; desc='Official HairSway manual covering installation, pin placement, Sway 1–8, Protection Pins, all Inspector parameters, and troubleshooting.'; lead='Basic HairSway workflow and a detailed reference for the controls shown in the Inspector.'; nav=[('Overview','#overview'),('Prepare layers','#prepare'),('Basic workflow','#basic'),('Parameters','#parameters'),('Protection Pins','#protection'),('Troubleshooting','#trouble')]
        content=f'''<h2 id="overview">Overview</h2><p>HairSway is a DaVinci Resolve / Fusion Fuse that automatically animates separated illustration layers such as hair, ribbons, and clothing hems without keyframes. It deforms the image locally along a chain of Viewer pins and supports up to eight independent Sways in one node.</p><h2 id="prepare">Prepare the image</h2><p>For best results, separate the parts you want to animate onto transparent layers. Typical examples include front hair, side hair, back hair, ribbons, and clothing hems. If the source is not layer-separated, isolate the target area with a Fusion tool such as Polygon before HairSway.</p><h2 id="basic">Basic workflow</h2><ol><li>Import the target layer into Fusion, add HairSway, and connect the image to its Input.</li><li>Open Sway 1 and enable <code class="inline">Enable Sway 1</code> and <code class="inline">Show Pins in Viewer</code>.</li><li>Choose <code class="inline">Pin Count</code>. Place the Root Pin at the base, then arrange the remaining pins in order toward the tip.</li><li>Reduce <code class="inline">Influence Radius</code> so it covers the target strand without unnecessary neighboring areas.</li><li>Play the timeline and tune Sway Distance, Speed, Tip Lag, Roundness, Root Lock, and Root Protection.</li></ol><div class="note">When setting multiple strands, hide the pins for a completed Sway before showing the next one. This makes Viewer controls easier to manage.</div><h2 id="parameters">Parameter reference</h2>{params_table(params,'en')}<h2 id="protection">Protection Pins</h2><p>Protection Pins keep specific areas from being deformed by any Sway. They are useful for the top of the head, face, ears, hair base, ribbon knots, or fixed clothing. Up to four Protection Pins are available.</p><p>If the scalp or face moves, review the Root Pin position, then Root Lock, Root Protection, Influence Radius, and finally add a Protection Pin if needed.</p><h2 id="trouble">Troubleshooting</h2><h3>The scalp or face moves</h3><ol><li>Place the Root Pin exactly at the hair/scalp boundary.</li><li>Increase Root Lock to roughly 0.30–0.45 and test.</li><li>Increase Root Protection.</li><li>Reduce Influence Radius to match the strand width.</li><li>Add a Protection Pin when needed.</li></ol><h3>Playback is slow</h3><p>Lower the Viewer proxy resolution, disable unused Sways, avoid unnecessary Sways, and temporarily disable other heavy nodes while editing. Return to full resolution for the final review.</p>'''
    nav_html='<strong>'+('このページの内容' if lang=='ja' else 'On this page')+'</strong>'+''.join(f'<a href="{u}">{t}</a>' for t,u in nav)+f'<a class="buy" href="https://soyorica.booth.pm/items/8676362">{"BOOTHで購入 →" if lang=="ja" else "Buy on BOOTH →"}</a>'
    body=head(title,desc,path,lang=lang,schema=hair_schema)+header(lang)+f'''<main id="main"><div class="container"><div class="docs-layout"><aside class="docs-nav">{nav_html}</aside><article class="article">{breadcrumbs([('Soyorica','/' if lang=='ja' else '/en/'),('説明書' if lang=='ja' else 'Manuals','/docs/' if lang=='ja' else '/en/docs/'),('HairSway','')],lang)}<p class="eyebrow">Manual / HairSway</p><h1>HairSway</h1><p class="article-lead">{lead}</p><div class="hero-actions"><a class="btn btn-secondary" href="{'/install/' if lang=='ja' else '/en/install/'}">{'インストール方法' if lang=='ja' else 'Installation'}</a></div>{content}</article></div></div></main>'''+footer(lang); write_page(path,body)

